using System;
using System.Runtime.CompilerServices;

namespace IAFahim.Search.Suffix
{
    public static unsafe class SuffixSums
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Run(long* ptr, int len)
        {
            if (len <= 0)
                return 0;
            for (int i = len - 2; i >= 0; i--)
                ptr[i] = ptr[i] + ptr[i + 1];
            return ptr[0];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Run(int* ptr, int len)
        {
            if (len <= 0)
                return 0;
            for (int i = len - 2; i >= 0; i--)
                ptr[i] = ptr[i] + ptr[i + 1];
            return ptr[0];
        }

        public static T Run<T>(T* ptr, int len) where T : unmanaged
        {
            if (len <= 0)
                return default;
            if (sizeof(T) == 4)
            {
                if (typeof(T) == typeof(float))
                {
                    float* p = (float*)ptr;
                    float sum = 0;
                    for (int i = 0; i < len; i++)
                        sum += p[i];
                    return *(T*)&sum;
                }
                int* pi = (int*)ptr;
                int sumi = 0;
                for (int i = 0; i < len; i++)
                    sumi += pi[i];
                return *(T*)&sumi;
            }
            else if (sizeof(T) == 8)
            {
                if (typeof(T) == typeof(double))
                {
                    double* p = (double*)ptr;
                    double sum = 0;
                    for (int i = 0; i < len; i++)
                        sum += p[i];
                    return *(T*)&sum;
                }
                long* pl = (long*)ptr;
                long suml = 0;
                for (int i = 0; i < len; i++)
                    suml += pl[i];
                return *(T*)&suml;
            }
            return default;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static T Sum<T>(T* ptr, int len) where T : unmanaged
        {
            return len > 0 ? ptr[0] : default;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static T RangeSum<T>(T* ptr, int l, int r) where T : unmanaged
        {
            if (l > r || l < 0)
                return default;
            if (sizeof(T) == 4)
            {
                if (typeof(T) == typeof(float))
                {
                    float* p = (float*)ptr;
                    float sum = 0;
                    for (int i = l; i <= r; i++)
                        sum += p[i];
                    return *(T*)&sum;
                }
                int* pi = (int*)ptr;
                int sumi = 0;
                for (int i = l; i <= r; i++)
                    sumi += pi[i];
                return *(T*)&sumi;
            }
            else if (sizeof(T) == 8)
            {
                if (typeof(T) == typeof(double))
                {
                    double* p = (double*)ptr;
                    double sum = 0;
                    for (int i = l; i <= r; i++)
                        sum += p[i];
                    return *(T*)&sum;
                }
                long* pl = (long*)ptr;
                long suml = 0;
                for (int i = l; i <= r; i++)
                    suml += pl[i];
                return *(T*)&suml;
            }
            return default;
        }
    }

    public static unsafe class SuffixMin
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static T Run<T>(T* ptr, int len) where T : unmanaged, IComparable<T>
        {
            if (len <= 0)
                return default;
            for (int i = len - 2; i >= 0; i--)
            {
                if (ptr[i].CompareTo(ptr[i + 1]) > 0)
                    ptr[i] = ptr[i + 1];
            }
            return ptr[0];
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int MinIndex<T>(T* ptr, int len) where T : unmanaged, IComparable<T>
        {
            if (len <= 0)
                return -1;
            int minIdx = len - 1;
            for (int i = len - 2; i >= 0; i--)
            {
                if (ptr[i].CompareTo(ptr[minIdx]) < 0)
                    minIdx = i;
            }
            return minIdx;
        }
    }

